func TestNumPages(t *testing.T) {
	for _, c := range []struct{ size, pages uint32 }{
		{20, 1}, {PAGE_SIZE - 1, 1}, {PAGE_SIZE, 1}, {PAGE_SIZE + 1, 2},
		{0xe0000, 56},
		{0xe0001, 57},
	} {
		if got := numPages(c.size); got != c.pages {
			t.Errorf("numPages(%#x) = %d, want %d", c.size, got, c.pages)
		}
	}
}

func TestValidateHeaderPages(t *testing.T) {
	hdr := PackedHeader{UnpackedSize: 0x1abfa0, PackedSize: 0xe0000, NumPages: 56, PageSize: PAGE_SIZE, Alignment: 4}
	if !validateHeader(&hdr) {
		t.Error("exact page multiple with ceil page count rejected")
	}
	hdr.NumPages = 57
	if validateHeader(&hdr) {
		t.Error("exact page multiple with size/PAGE_SIZE+1 pages accepted")
	}
	hdr = PackedHeader{UnpackedSize: 0x925c5, PackedSize: 0x6e7c4, NumPages: 28, PageSize: PAGE_SIZE, Alignment: 4}
	if !validateHeader(&hdr) {
		t.Error("ordinary header rejected")
	}
}

func pack(t *testing.T, data []byte) ([]byte, []string) {
	t.Helper()
	packed, warnings, err := tryPack(data, false)
	if err != nil {
		t.Fatal(err)
	}
	return packed, warnings
}

func tryPack(data []byte, dirty bool) ([]byte, []string, error) {
	var warnings []string
	saved := Warn
	Warn = func(msg string) { warnings = append(warnings, msg) }
	defer func() { Warn = saved }()
	var out bytes.Buffer
	hdr, err := PackIO(bytes.NewReader(data), &out, dirty)
	if err != nil {
		return nil, warnings, err
	}
	var packed bytes.Buffer
	packed.Write([]byte{byte(hdr.UnpackedSize), byte(hdr.UnpackedSize >> 8), byte(hdr.UnpackedSize >> 16), byte(hdr.UnpackedSize >> 24)})
	for _, v := range []uint32{hdr.PackedSize, hdr.NumPages, hdr.PageSize, hdr.Alignment} {
		packed.Write([]byte{byte(v), byte(v >> 8), byte(v >> 16), byte(v >> 24)})
	}
	packed.Write(out.Bytes())
	return packed.Bytes(), warnings, nil
}

func unpack(t *testing.T, packed []byte) ([]byte, []string) {
	t.Helper()
	var warnings []string
	saved := Warn
	Warn = func(msg string) { warnings = append(warnings, msg) }
	defer func() { Warn = saved }()
	var out bytes.Buffer
	if _, err := UnpackIO(bytes.NewReader(packed), &out); err != nil {
		t.Fatal(err)
	}
	return out.Bytes(), warnings
}

func lcgBytes(n int) []byte {
	b := make([]byte, n)
	x := uint32(72)
	for i := range b {
		x = x*1103515245 + 12345
		b[i] = byte(x >> 16)
	}
	return b
}

func streamEnds(t *testing.T, tail int) map[string][]int {
	t.Helper()
	ends := map[string][]int{}
	for n := 15000; n < 15600; n++ {
		data := append(append(make([]byte, 8000), lcgBytes(n)...), make([]byte, tail)...)
		_, _, err := tryPack(data, false)
		end := ""
		if err != nil {
			msg := err.Error()
			if !strings.HasPrefix(msg, "LZ pack: the data ends with ") || !strings.HasSuffix(msg, ", #275)") {
				t.Fatalf("%d bytes: %v", n, err)
			}
			for _, what := range []string{"would cross a page boundary", "would leave 1 byte on its page",
				"an all-zero copy of", "an all-zero literal of", "alone on a new page"} {
				if strings.Contains(msg, what) {
					end = what
					break
				}
			}
			if end == "" {
				t.Fatalf("%d bytes: %v", n, err)
			}
		}
		ends[end] = append(ends[end], n)
	}
	return ends
}

func roundTrip(t *testing.T, data []byte, dirty bool) []string {
	t.Helper()
	packed, warnings, err := tryPack(data, dirty)
	if err != nil {
		t.Fatal(err)
	}
	if got, _ := unpack(t, packed); !bytes.Equal(got, data) {
		t.Fatalf("%d bytes: unpacked %d", len(data), len(got))
	}
	return warnings
}

func guessed(t *testing.T, warnings []string, what string, more ...string) {
	t.Helper()
	if !warningsEnabled {
		if len(warnings) != 0 {
			t.Fatalf("warnings in a release build: %v", warnings)
		}
		return
	}
	want := append([]string{"packed by guess (--dirty-tricks, #275)"}, more...)
	if len(warnings) != len(want) || !strings.Contains(warnings[0], what) {
		t.Fatalf("warnings %v, want %q then %v", warnings, what, more)
	}
	for i, w := range want {
		if !strings.Contains(warnings[i], w) {
			t.Fatalf("warning %d %q, want %q", i, warnings[i], w)
		}
	}
}

func TestFinalZeroCopyOfTwoDropped(t *testing.T) {
	if !warningsEnabled {
		t.Skip("the drop is seen by its warning")
	}
	dropped := 0
	for i := range 40 * 40 {
		n, tail := 15130+i/40, 3+i%40
		data := append(append(make([]byte, 8000), lcgBytes(n)...), make([]byte, tail)...)
		packed, warnings, err := tryPack(data, false)
		if err != nil {
			continue
		}
		got, uwarnings := unpack(t, packed)
		if !bytes.Equal(got, data) {
			t.Fatalf("%d bytes: unpacked data differs from the input", n)
		}
		if len(warnings) == 0 {
			continue
		}
		dropped++
		if len(warnings) != 1 || !strings.Contains(warnings[0], "final all-zero token (2 bytes)") || len(packed) != PAGE_SIZE {
			t.Fatalf("%d bytes: pack warnings %v, %#x bytes", n, warnings, len(packed))
		}
		if len(uwarnings) != 1 || !strings.Contains(uwarnings[0], "zero-filled") {
			t.Fatalf("unpack warnings: %v", uwarnings)
		}
	}
	if dropped == 0 {
		t.Fatal("no input whose final 2-byte zero copy starts a new page")
	}
}

func TestFinalZeroTokenAtPageBoundary(t *testing.T) {
	ends := streamEnds(t, 27)
	if len(ends["an all-zero copy of"]) == 0 {
		t.Fatalf("no input whose final zero copy starts a new page: %v", ends)
	}
	for _, n := range ends["an all-zero copy of"] {
		data := append(append(make([]byte, 8000), lcgBytes(n)...), make([]byte, 27)...)
		guessed(t, roundTrip(t, data, true), "an all-zero copy of ", "final all-zero token (")
	}
}

